insert into public.portfolio_projects (id,title,description,intro,story,approach,status_note,tags,cover_url,cover_color,cover_layout,gallery,repository_url,demo_url,published,archived,sort_order)
values ('pjtsau','PJTSAU · Crop Diagnostics','Featured freelance work · A connected platform for crop care.','A mobile application and centralized web dashboard for the detection and diagnosis of insect pests and crop diseases, developed through a collaboration between PJTAU and K L University, Hyderabad.','Bringing field observations and expert guidance into one connected workflow. The platform supports geo-referenced image capture, expert validation, structured case allocation, and treatment advisories for pest and crop disease management.','My role was Full Stack Development within a seven-member team. The project connects a mobile application with a database-driven web dashboard through automated data synchronization and secure two-way communication.','Completed: 25 August 2024 – 25 January 2025. The university''s completion certificate, dated 25 January 2025, acknowledges Tadivaka Sathwik for Full Stack Development. The certificate recognizes the successful completion of the prototype.',array['Freelance','Full-stack','Mobile + Web','Digital agriculture'],'/assets/pjtsau-certificate.webp','mint','{"template": "browser", "eyebrow": "FEATURED FREELANCE WORK / PJTSAU", "headline": "From field.\nTo insight.", "footer": "FULL-STACK / PROJECT COMPLETED", "windowLabel": "university completion certificate", "rotation": -4, "imageY": 0, "fit": "cover"}'::jsonb,'[]'::jsonb,'','/pjtsau/',true,false,-1)
on conflict (id) do nothing;
